def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 1:
            return float(min(budget, DAILY_SALARY * 0.85))
        return float(min(budget, DAILY_SALARY * 0.35))

    prev_bids = []
    prev_high_need = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace') or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                prev_high_need.append(float(bid))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    highest_desperate = max(prev_high_need) if prev_high_need else 0.0

    total_alive = len(alive_opponents) + 1
    expected_units = supply / float(WATER_REQ)
    scarcity = expected_units < total_alive
    very_tight = expected_units < max(1.5, total_alive * 0.6)

    danger = hp <= 2 or no_water_days >= 1
    moderate_risk = hp <= 4

    if danger:
        target = max(DAILY_SALARY * 0.92, highest_prev + 2.0, highest_desperate + 1.0)
        if very_tight:
            target = max(target, DAILY_SALARY * 1.08)
        return float(min(budget, target))

    if scarcity:
        if highest_prev >= DAILY_SALARY * 1.35:
            target = DAILY_SALARY * 0.42 if hp >= 6 else DAILY_SALARY * 0.88
        elif highest_prev >= DAILY_SALARY * 1.0:
            target = highest_prev + 1.5 if moderate_risk else DAILY_SALARY * 0.58
        else:
            target = max(DAILY_SALARY * 0.62, highest_prev + 2.0)
        if very_tight:
            target += 6.0
    else:
        if highest_prev >= DAILY_SALARY * 1.25:
            target = DAILY_SALARY * 0.28
        elif highest_prev >= DAILY_SALARY * 0.9:
            target = DAILY_SALARY * 0.4
        else:
            target = max(DAILY_SALARY * 0.34, highest_prev * 0.72)

    if day >= 8 and hp >= 6:
        target *= 0.9
    if day >= 8 and moderate_risk:
        target = max(target, DAILY_SALARY * 0.72)

    reserve_floor = 0.0
    if hp >= 5 and day <= 7:
        reserve_floor = max(0.0, budget - DAILY_SALARY * 2.2)
        target = min(target, max(reserve_floor, 0.0) if reserve_floor > 0 else target)

    target = max(0.0, min(budget, target))
    return float(target)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    my_hp = int(my_status['hp'])
    my_budget = float(my_status['budget'])

    alive = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive.append((opp_id, opp))

    if not alive:
        return min(my_budget, DAILY_SALARY * 0.4)

    # Read yesterday bids from previous_trace only
    prev_bids = []
    prev_max = 0.0
    prev_min = None
    for opp_id, opp in alive:
        tr = opp.get('previous_trace', {})
        b = tr.get('bid', None)
        if b is not None:
            try:
                b = float(b)
            except Exception:
                continue
            prev_bids.append(b)
            if b > prev_max:
                prev_max = b
            if prev_min is None or b < prev_min:
                prev_min = b

    # Estimate how aggressive the field was yesterday
    # Eric-like behavior: very high bids near/above DAILY_SALARY.
    aggressive = prev_max >= DAILY_SALARY * 0.9

    # Supply pressure: if supply is low, water is scarce; need more to secure survival.
    scarcity = 1.0
    if supply >= 22.0:
        scarcity = 0.75
    elif supply <= 17.0:
        scarcity = 1.15

    # If we're low HP, we must secure water.
    if my_hp <= 2:
        target = DAILY_SALARY * 0.9 * scarcity
        return min(my_budget, target)

    # If others were aggressive yesterday, bid enough to beat them but not match max.
    # Use a small overtake strategy: bid around 0.65-0.78 of DAILY_SALARY.
    if aggressive:
        # If our HP is decent, we can stay below the top bid.
        base = DAILY_SALARY * 0.72
        if my_hp >= 7:
            base = DAILY_SALARY * 0.62
        # If supply is very scarce, raise slightly.
        if scarcity > 1.0:
            base *= 1.08
        # Ensure we don't overspend beyond budget.
        return min(my_budget, base)

    # Otherwise, bid moderately to conserve budget.
    # Aim to cover our 9-water requirement efficiently: one unit of WATER_REQ is 9.
    # Convert to a heuristic bid fraction based on how much of the supply likely matters.
    # With supply in [15,25], at least 1 full requirement is possible; bid around 0.55-0.65 salary.
    base = DAILY_SALARY * (0.6 if my_hp >= 5 else 0.72)
    base *= scarcity

    # If we have very low budget, cap down.
    if my_budget <= DAILY_SALARY * 0.45:
        base = min(base, my_budget)

    return min(my_budget, base)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    alive_opps = [o for o in opponents_status.values() if o['alive']]

    max_prev_bid = 0
    for opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            if prev['bid'] > max_prev_bid:
                max_prev_bid = prev['bid']

    urgency = my_status['no_water_days'] * 15 + max(0, 10 - my_status['hp']) * 10

    if my_status['hp'] <= 2 or my_status['no_water_days'] >= 1:
        bid = min(my_status['budget'], max(DAILY_SALARY * 0.9, max_prev_bid + 2))
    elif urgency > 30:
        bid = min(my_status['budget'], max(DAILY_SALARY * 0.7, max_prev_bid + 1))
    else:
        bid = min(my_status['budget'], DAILY_SALARY * 0.5)
        if max_prev_bid > DAILY_SALARY * 0.8:
            bid = min(my_status['budget'], max(bid, DAILY_SALARY * 0.6))

    bid = max(0, min(bid, my_status['budget']))
    return bid
